package cn.binbin.crm;

import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.*;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.stereotype.Service;

@Service
public class SalesOrderService {
 public record Create(@NotNull UUID quoteId,@Min(0) long quoteExpectedVersion,@NotBlank @Size(max=200) String title,LocalDate expectedDeliveryDate,@Size(max=4000) String notes){}
 public record Edit(@NotBlank @Size(max=200) String title,LocalDate expectedDeliveryDate,@Size(max=4000) String notes,@Min(0) long expectedVersion){}
 public record Decision(@Min(0) long expectedVersion,@Size(max=500) String reason){}
 public record Delivery(@NotNull UUID lineId,@NotNull @DecimalMin("0.0000") BigDecimal deliveredQuantity){}
 public record Fulfillment(@Min(0) long expectedVersion,@NotEmpty @Size(max=100) List<@Valid Delivery> lines){}
 record Target(UUID id,Object input){}
 private final NamedParameterJdbcTemplate db;private final TradeService trade;private final CommerceService commerce;
 public SalesOrderService(NamedParameterJdbcTemplate db,TradeService trade,CommerceService commerce){this.db=db;this.trade=trade;this.commerce=commerce;}
 static Map<String,Object> p(Object... values){return TradeService.map(values);}
 static final String FROM=" FROM crm_sales_order k JOIN crm_customer c ON c.tenant_id=k.tenant_id AND c.id=k.customer_id JOIN sys_tenant_member m ON m.tenant_id=k.tenant_id AND m.id=k.owner_member_id LEFT JOIN crm_opportunity o ON o.tenant_id=k.tenant_id AND o.id=k.opportunity_id ";
 static final String READ="k.tenant_id=:tenant AND :contractReader AND "+CustomerService.READ+" AND "+TradeService.own("k","m",false)+" AND (k.opportunity_id IS NULL OR "+SalesService.OP_READ+")";
 static final String WRITE="(:contractWriter AND "+CustomerService.WRITE+" AND "+TradeService.own("k","m",true)+" AND (k.opportunity_id IS NULL OR "+SalesService.OP_WRITE+"))";
 static final String SELECT="SELECT k.*, ("+WRITE+") AS can_manage, (k.status='DRAFT' AND "+WRITE+") AS can_write,(SELECT ct.id FROM crm_contract ct WHERE ct.tenant_id=k.tenant_id AND ct.order_id=k.id) AS contract_id"+FROM;
 private Map<String,Object> params(AuthService.Actor a){return trade.params(a);}
 private void date(LocalDate d){if(d!=null)TradeService.date(d);}
 Map<String,Object> detail(AuthService.Actor a,UUID id){var params=params(a);params.put("id",id);var order=trade.one(SELECT+"WHERE "+READ+" AND k.id=:id",params);order.remove("quoteSnapshot");var lines=trade.rows("SELECT id,line_number,product_id,sku_snapshot,name_snapshot,unit_snapshot,quantity,delivered_quantity,unit_price_cents,cost_cents,discount_bps,amount_cents,description FROM crm_sales_order_line WHERE tenant_id=:tenant AND order_id=:id ORDER BY line_number",params);if(!a.commerceAccess().productWrite()){order.remove("estimatedCostCents");lines.forEach(line->line.remove("costCents"));}order.put("lines",lines);return order;}
 public Object one(AuthService.Session s,UUID id){return trade.scoped(s,"contract",false,a->detail(a,id));}
 public Object list(AuthService.Session s,int page,int size,String q,String state,UUID customer){TradeService.page(page,size,q);if(!Set.of("","DRAFT","CONFIRMED","IN_DELIVERY","DELIVERED","VOID").contains(state))throw ApiError.bad("订单状态无效");return trade.scoped(s,"contract",false,a->{var x=params(a);x.putAll(p("q",TradeService.text(q).toLowerCase(Locale.ROOT),"state",state,"customer",customer,"limit",size,"offset",((long)page-1)*size));String where=READ+" AND(:state='' OR k.status=:state) AND(cast(:customer AS uuid) IS NULL OR k.customer_id=:customer) AND(:q='' OR strpos(lower(k.order_number),:q)>0 OR strpos(lower(k.title),:q)>0 OR strpos(lower(k.customer_name_snapshot),:q)>0)";var items=trade.rows(SELECT+" WHERE "+where+" ORDER BY k.updated_at DESC,k.id LIMIT :limit OFFSET :offset",x);items.forEach(row->{row.remove("quoteSnapshot");if(!a.commerceAccess().productWrite())row.remove("estimatedCostCents");});return new BusinessService.Page<>(items,page,size,db.queryForObject("SELECT count(*)"+FROM+"WHERE "+where,x,Long.class));});}
 public Object quoteOptions(AuthService.Session s,int page,int size,String q,UUID customer){TradeService.page(page,size,q);return trade.scoped(s,"contract",false,a->{if(!a.tradeAccess().contracts().write()||!a.commerceAccess().quotes().read()||!a.canWriteCustomers())throw ApiError.forbidden("需要订单写入和报价读取权限");var x=commerce.params(a);x.putAll(params(a));x.putAll(p("q",TradeService.text(q).toLowerCase(Locale.ROOT),"customer",customer,"limit",size,"offset",((long)page-1)*size));String where=CommerceService.READ+" AND q.status='APPROVED' AND q.valid_until>=:today AND :contractWriter AND "+CustomerService.WRITE+" AND "+TradeService.own("q","m",true)+" AND(q.opportunity_id IS NULL OR "+SalesService.OP_WRITE+") AND NOT EXISTS(SELECT 1 FROM crm_sales_order k WHERE k.tenant_id=q.tenant_id AND k.quote_id=q.id AND k.quote_version=q.version) AND NOT EXISTS(SELECT 1 FROM crm_contract_quote_link l WHERE l.tenant_id=q.tenant_id AND l.quote_id=q.id AND l.quote_version=q.version) AND(cast(:customer AS uuid) IS NULL OR q.customer_id=:customer) AND(:q='' OR strpos(lower(q.quote_number),:q)>0 OR strpos(lower(q.title),:q)>0)";return new BusinessService.Page<>(trade.rows("SELECT q.id,q.quote_number,q.title,q.customer_id,q.customer_name_snapshot,q.total_cents,q.version"+CommerceService.FROM+"WHERE "+where+" ORDER BY q.updated_at DESC,q.id LIMIT :limit OFFSET :offset",x),page,size,db.queryForObject("SELECT count(*)"+CommerceService.FROM+"WHERE "+where,x,Long.class));});}
 public Object create(AuthService.Session s,Create input,String key,UUID trace){return trade.scoped(s,"contract",true,a->{if(!a.canWriteCustomers()||!a.commerceAccess().quotes().read())throw ApiError.forbidden("需要客户写入和报价读取权限");UUID id=trade.once(a,"sales-order.create",key,input,()->{var q=trade.basis(a,input.quoteId(),input.quoteExpectedVersion());int used=db.queryForObject("SELECT count(*) FROM crm_sales_order WHERE tenant_id=:tenant AND quote_id=:quote AND quote_version=:version",p("tenant",a.tenant().id(),"quote",input.quoteId(),"version",input.quoteExpectedVersion()),Integer.class);if(used!=0)throw ApiError.conflict("该批准报价版本已转换为订单");date(input.expectedDeliveryDate());var lines=trade.rows("SELECT * FROM crm_quote_line WHERE tenant_id=:tenant AND quote_id=:quote ORDER BY line_number",p("tenant",a.tenant().id(),"quote",input.quoteId()));if(lines.isEmpty())throw ApiError.conflict("报价没有产品明细");long total=0,cost=0;for(var line:lines){total=QuoteAmounts.add(total,TradeService.number(line,"amountCents"));cost=QuoteAmounts.add(cost,QuoteAmounts.line((BigDecimal)line.get("quantity"),TradeService.number(line,"costCents"),0));}if(total!=TradeService.number(q,"totalCents"))throw ApiError.conflict("报价金额与明细不一致");var x=params(a);x.put("year",TradeService.today().getYear());long seq=db.queryForObject("INSERT INTO crm_sales_order_counter(tenant_id,order_year,next_value) VALUES(:tenant,:year,1) ON CONFLICT(tenant_id,order_year) DO UPDATE SET next_value=crm_sales_order_counter.next_value+1 RETURNING next_value",x,Long.class);UUID created=UUID.randomUUID();x.putAll(p("id",created,"number",P4Numbering.format(db,a.tenant().id(),"ORDER",TradeService.today().getYear(),seq,"SO"),"title",TradeService.text(input.title()),"customer",q.get("customerId"),"opportunity",q.get("opportunityId"),"owner",q.get("ownerMemberId"),"quote",input.quoteId(),"qversion",input.quoteExpectedVersion(),"snapshot",trade.body(commerce.revisionForTrade(a,input.quoteId(),input.quoteExpectedVersion())),"customerName",q.get("customerNameSnapshot"),"ownerName",q.get("ownerNameSnapshot"),"total",total,"cost",cost,"date",input.expectedDeliveryDate(),"notes",TradeService.text(input.notes())));db.update("INSERT INTO crm_sales_order(id,tenant_id,order_number,title,customer_id,opportunity_id,owner_member_id,created_by_member_id,quote_id,quote_version,quote_snapshot,customer_name_snapshot,owner_name_snapshot,total_cents,estimated_cost_cents,expected_delivery_date,notes) VALUES(:id,:tenant,:number,:title,:customer,:opportunity,:owner,:member,:quote,:qversion,cast(:snapshot AS jsonb),:customerName,:ownerName,:total,:cost,:date,:notes)",x);for(var line:lines){var l=p("id",UUID.randomUUID(),"tenant",a.tenant().id(),"order",created,"line",line.get("lineNumber"),"product",line.get("productId"),"sku",line.get("skuSnapshot"),"name",line.get("nameSnapshot"),"unit",line.get("unitSnapshot"),"quantity",line.get("quantity"),"price",line.get("unitPriceCents"),"cost",line.get("costCents"),"discount",line.get("discountBps"),"amount",line.get("amountCents"),"description",line.get("description"));db.update("INSERT INTO crm_sales_order_line(id,tenant_id,order_id,line_number,product_id,sku_snapshot,name_snapshot,unit_snapshot,quantity,unit_price_cents,cost_cents,discount_bps,amount_cents,description) VALUES(:id,:tenant,:order,:line,:product,:sku,:name,:unit,:quantity,:price,:cost,:discount,:amount,:description)",l);}event(a,created,"CREATED","",trace);return created;});return detail(a,id);});}
 public Object edit(AuthService.Session s,UUID id,Edit input,UUID trace){return trade.scoped(s,"contract",true,a->{var order=detail(a,id);if(!Boolean.TRUE.equals(order.get("canWrite")))throw ApiError.forbidden("只有可管理的订单草稿能修改");date(input.expectedDeliveryDate());int n=db.update("UPDATE crm_sales_order SET title=:title,expected_delivery_date=:date,notes=:notes,version=version+1,updated_at=now() WHERE tenant_id=:tenant AND id=:id AND version=:version AND status='DRAFT'",p("tenant",a.tenant().id(),"id",id,"version",input.expectedVersion(),"title",TradeService.text(input.title()),"date",input.expectedDeliveryDate(),"notes",TradeService.text(input.notes())));if(n!=1)throw ApiError.conflict("订单已变化，请刷新");event(a,id,"UPDATED","",trace);return detail(a,id);});}
 public Object action(AuthService.Session s,UUID id,String action,Decision input,String key,UUID trace){return trade.scoped(s,"contract",true,a->{UUID selected=trade.once(a,"sales-order."+action,key,new Target(id,input),()->{var order=detail(a,id);if(!Boolean.TRUE.equals(order.get("canManage")))throw ApiError.forbidden("无权处理此订单");String state=(String)order.get("status"),next;String reason=TradeService.text(input.reason());if("confirm".equals(action)){if(!"DRAFT".equals(state))throw ApiError.conflict("只有草稿可确认");commerce.approvedForTrade(a,(UUID)order.get("quoteId"),TradeService.number(order,"quoteVersion"));var rule=trade.one("SELECT max_discount_bps,min_margin_bps FROM crm_approval_rule WHERE tenant_id=:tenant AND process_type='QUOTE'",p("tenant",a.tenant().id()));var lines=trade.rows("SELECT quantity,cost_cents,discount_bps FROM crm_sales_order_line WHERE tenant_id=:tenant AND order_id=:id ORDER BY line_number",p("tenant",a.tenant().id(),"id",id));PricingRules.enforce(TradeService.number(order,"totalCents"),lines.stream().map(l->new PricingRules.Line((BigDecimal)l.get("quantity"),TradeService.number(l,"costCents"),((Number)l.get("discountBps")).intValue())).toList(),((Number)rule.get("maxDiscountBps")).intValue(),((Number)rule.get("minMarginBps")).intValue());next="CONFIRMED";}else if("void".equals(action)){if(!Set.of("DRAFT","CONFIRMED").contains(state)||order.get("contractId")!=null)throw ApiError.conflict("已履约或已关联合同的订单不能作废");if(reason.isEmpty())throw ApiError.bad("请填写作废原因");next="VOID";}else throw ApiError.bad("订单动作无效");int n=db.update("UPDATE crm_sales_order SET status=:next,confirmed_at=CASE WHEN :next='CONFIRMED' THEN now() ELSE confirmed_at END,void_reason=CASE WHEN :next='VOID' THEN :reason ELSE void_reason END,version=version+1,updated_at=now() WHERE tenant_id=:tenant AND id=:id AND version=:version",p("tenant",a.tenant().id(),"id",id,"version",input.expectedVersion(),"next",next,"reason",reason));if(n!=1)throw ApiError.conflict("订单已变化，请刷新");event(a,id,action.toUpperCase(Locale.ROOT),reason,trace);return id;});return detail(a,selected);});}
 public Object fulfill(AuthService.Session s,UUID id,Fulfillment input,UUID trace){return trade.scoped(s,"contract",true,a->{var order=detail(a,id);if(!Boolean.TRUE.equals(order.get("canManage"))||!Set.of("CONFIRMED","IN_DELIVERY","DELIVERED").contains(order.get("status")))throw ApiError.forbidden("只有已确认且可管理的订单能登记履约");@SuppressWarnings("unchecked") var lines=(List<Map<String,Object>>)order.get("lines");if(input.lines().size()!=lines.size())throw ApiError.bad("请提交全部订单明细的履约数量");var values=new HashMap<UUID,BigDecimal>();for(var l:input.lines()){if(l.lineId()==null||l.deliveredQuantity()==null||l.deliveredQuantity().scale()>4||values.putIfAbsent(l.lineId(),l.deliveredQuantity())!=null)throw ApiError.bad("履约明细无效或重复");}int done=0;boolean any=false;for(var line:lines){BigDecimal v=values.get(line.get("id")),quantity=(BigDecimal)line.get("quantity"),old=(BigDecimal)line.get("deliveredQuantity");if(v==null||v.compareTo(old)<0||v.compareTo(quantity)>0)throw ApiError.conflict("履约数量不能倒退或超过订单数量");if(v.signum()>0)any=true;if(v.compareTo(quantity)==0)done++;}String state=done==lines.size()?"DELIVERED":any?"IN_DELIVERY":"CONFIRMED";int n=db.update("UPDATE crm_sales_order SET status=:state,version=version+1,updated_at=now() WHERE tenant_id=:tenant AND id=:id AND version=:version",p("tenant",a.tenant().id(),"id",id,"version",input.expectedVersion(),"state",state));if(n!=1)throw ApiError.conflict("订单已变化，请刷新");for(var line:lines)db.update("UPDATE crm_sales_order_line SET delivered_quantity=:quantity WHERE tenant_id=:tenant AND order_id=:id AND id=:line",p("tenant",a.tenant().id(),"id",id,"line",line.get("id"),"quantity",values.get(line.get("id"))));event(a,id,"FULFILLMENT","",trace);return detail(a,id);});}
 public Object history(AuthService.Session s,UUID id,int page,int size){TradeService.page(page,size,"");return trade.scoped(s,"contract",false,a->{detail(a,id);var x=p("tenant",a.tenant().id(),"id",id,"limit",size,"offset",((long)page-1)*size);return new BusinessService.Page<>(trade.rows("SELECT business_version,action,actor_name_snapshot,reason,created_at FROM crm_sales_order_event WHERE tenant_id=:tenant AND order_id=:id ORDER BY business_version DESC LIMIT :limit OFFSET :offset",x),page,size,db.queryForObject("SELECT count(*) FROM crm_sales_order_event WHERE tenant_id=:tenant AND order_id=:id",x,Long.class));});}
 private void event(AuthService.Actor a,UUID id,String action,String reason,UUID trace){var x=p("tenant",a.tenant().id(),"id",id);var order=trade.one("SELECT order_number,status,total_cents,quote_id,quote_version,version FROM crm_sales_order WHERE tenant_id=:tenant AND id=:id",x);order.put("lines",trade.rows("SELECT line_number,quantity,delivered_quantity,amount_cents FROM crm_sales_order_line WHERE tenant_id=:tenant AND order_id=:id ORDER BY line_number",x));db.update("INSERT INTO crm_sales_order_event(id,tenant_id,order_id,business_version,action,snapshot,actor_member_id,actor_name_snapshot,reason) VALUES(:event,:tenant,:id,:version,:action,cast(:snapshot AS jsonb),:member,:name,:reason)",p("event",UUID.randomUUID(),"tenant",a.tenant().id(),"id",id,"version",order.get("version"),"action",action,"snapshot",trade.body(order),"member",a.tenant().memberId(),"name",a.tenant().memberName(),"reason",reason));trade.audit(a,"ORDER_"+action,"SALES_ORDER",id,TradeService.number(order,"version"),trace);}
}
